const hits = $input.first().json.hits || [];
const hiring = hits.find((h) => /Who is hiring/i.test(h.title || ''));
if (!hiring) {
  throw new Error('Could not find current "Ask HN: Who is hiring?" story in whoishiring author feed -- feed shape may have changed.');
}
return [{
  json: {
    story_id: hiring.objectID,
    story_title: hiring.title,
    fetch_url: `https://hn.algolia.com/api/v1/search_by_date?tags=comment,story_${hiring.objectID}&hitsPerPage=20`,
  },
}];

const incoming = $input.all();

let existingText = '';
try {
  existingText = $('Extract From File').first()?.json?.data || '';
} catch (e) {
  throw new Error(`Failed to read existing storage: ${e.message}`);
}

const existingUrls = new Set(
  existingText.split('\n').filter(Boolean).map(line => {
    try { return JSON.parse(line).source_url; } catch { return null; }
  }).filter(Boolean)
);

const storyId = Number($('Build Comment Query').first().json.story_id);

const PLACEHOLDER = 'Unclassified — pending AI extraction';

const topLevelOnly = incoming.filter((item) => item.json.parent_id === storyId);

const normalized = topLevelOnly.map((item) => {
  const hit = item.json;
  const objectID = hit.objectID;
  const sourceUrl = `https://news.ycombinator.com/item?id=${objectID}`;
  const bodyText = hit.comment_text || '';
  const title = bodyText ? bodyText.replace(/<[^>]*>/g, ' ').trim().slice(0, 120) : '(untitled)';
  const rawText = bodyText;

  return {
    signal_id: `hn-${objectID}`,
    source_type: 'public_api',
    source_name: 'Hacker News (Who is Hiring? monthly thread, via Algolia Search API)',
    source_url: sourceUrl,
    signal_date: hit.created_at,
    market: PLACEHOLDER,
    opportunity_category: PLACEHOLDER,
    opportunity_title: title,
    problem: rawText,
    target_customer: PLACEHOLDER,
    demand_signal: rawText,
    proposed_solution: PLACEHOLDER,
    monetization_model: PLACEHOLDER,
    delivery_method: PLACEHOLDER,
    geography: PLACEHOLDER,
    evidence_notes: `Raw signal ingested from Hacker News "Who is hiring?" monthly thread via Algolia Search API. HN objectID ${objectID}, top-level job posting comment. Not yet human-reviewed.`,
    _dedupe_url: sourceUrl
  };
});

const fresh = normalized.filter((rec) => !existingUrls.has(rec._dedupe_url));

return fresh.map((rec) => {
  const { _dedupe_url, ...clean } = rec;
  return { json: clean };
});
